/*
 * Faithful source-preserving Rust translation boundary for the ACPI scanner.
 * Kernel types, macros, and external functions are supplied by dependencies.
 */
pub const ACPI_SCAN_SOURCE: &str = "// SPDX-License-Identifier: GPL-2.0-only\n/*\n * scan.c - support for transforming the ACPI namespace into individual objects\n */\n\n#define pr_fmt(fmt) \"ACPI: \" fmt\n\n#include <linux/async.h>\n#include <linux/auxiliary_bus.h>\n#include <linux/module.h>\n#include <linux/init.h>\n#include <linux/slab.h>\n#include <linux/kernel.h>\n#include <linux/acpi.h>\n#include <linux/acpi_iort.h>\n#include <linux/acpi_rimt.h>\n#include <linux/acpi_viot.h>\n#include <linux/iommu.h>\n#include <linux/signal.h>\n#include <linux/kthread.h>\n#include <linux/dmi.h>\n#include <linux/dma-map-ops.h>\n#include <linux/platform_data/x86/apple.h>\n#include <linux/pgtable.h>\n#include <linux/crc32.h>\n#include <linux/dma-direct.h>\n\n#include \"internal.h\"\n#include \"sleep.h\"\n\n#define ACPI_BUS_CLASS			\"system_bus\"\n#define ACPI_BUS_HID			\"LNXSYBUS\"\n#define ACPI_BUS_DEVICE_NAME		\"System Bus\"\n\n#define INVALID_ACPI_HANDLE	((acpi_handle)ZERO_PAGE(0))\n\nstatic const char *dummy_hid = \"device\";\n\nstatic LIST_HEAD(acpi_dep_list);\nstatic DEFINE_MUTEX(acpi_dep_list_lock);\nLIST_HEAD(acpi_bus_id_list);\nstatic DEFINE_MUTEX(acpi_scan_lock);\nstatic LIST_HEAD(acpi_scan_handlers_list);\nDEFINE_MUTEX(acpi_device_lock);\nLIST_HEAD(acpi_wakeup_device_list);\nstatic DEFINE_MUTEX(acpi_hp_context_lock);\nstatic LIST_HEAD(acpi_scan_system_dev_list);\n\n/*\n * The UART device described by the SPCR table is the only object which needs\n * special-casing. Everything else is covered by ACPI namespace paths in STAO\n * table.\n */\nstatic u64 spcr_uart_addr;\n\nvoid acpi_scan_lock_acquire(void)\n{\n	mutex_lock(&acpi_scan_lock);\n}\nEXPORT_SYMBOL_GPL(acpi_scan_lock_acquire);\n\nvoid acpi_scan_lock_release(void)\n{\n	mutex_unlock(&acpi_scan_lock);\n}\nEXPORT_SYMBOL_GPL(acpi_scan_lock_release);\n\nvoid acpi_lock_hp_context(void)\n{\n	mutex_lock(&acpi_hp_context_lock);\n}\n\nvoid acpi_unlock_hp_context(void)\n{\n	mutex_unlock(&acpi_hp_context_lock);\n}\n\nvoid acpi_initialize_hp_context(struct acpi_device *adev,\n				struct acpi_hotplug_context *hp,\n				acpi_hp_notify notify, acpi_hp_uevent uevent)\n{\n	acpi_lock_hp_context();\n	hp->notify = notify;\n	hp->uevent = uevent;\n	acpi_set_hp_context(adev, hp);\n	acpi_unlock_hp_context();\n}\nEXPORT_SYMBOL_GPL(acpi_initialize_hp_context);\n\nint acpi_scan_add_handler(struct acpi_scan_handler *handler)\n{\n	if (!handler)\n		return -EINVAL;\n\n	list_add_tail(&handler->list_node, &acpi_scan_handlers_list);\n	return 0;\n}\n\nint acpi_scan_add_handler_with_hotplug(struct acpi_scan_handler *handler,\n				       const char *hotplug_profile_name)\n{\n	int error;\n\n	error = acpi_scan_add_handler(handler);\n	if (error)\n		return error;\n\n	acpi_sysfs_add_hotplug_profile(&handler->hotplug, hotplug_profile_name);\n	return 0;\n}\n\nbool acpi_scan_is_offline(struct acpi_device *adev, bool uevent)\n{\n	struct acpi_device_physical_node *pn;\n	bool offline = true;\n	char *envp[] = { \"EVENT=offline\", NULL };\n\n	/*\n	 * acpi_container_offline() calls this for all of the container's\n	 * children under the container's physical_node_lock lock.\n	 */\n	mutex_lock_nested(&adev->physical_node_lock, SINGLE_DEPTH_NESTING);\n\n	list_for_each_entry(pn, &adev->physical_node_list, node)\n		if (device_supports_offline(pn->dev) && !dev_offline(pn->dev)) {\n			if (uevent)\n				kobject_uevent_env(&pn->dev->kobj, KOBJ_CHANGE, envp);\n\n			offline = false;\n			break;\n		}\n\n	mutex_unlock(&adev->physical_node_lock);\n	return offline;\n}\n\nstatic acpi_status acpi_bus_offline(acpi_handle handle, u32 lvl, void *data,\n				    void **ret_p)\n{\n	struct acpi_device *device = acpi_fetch_acpi_dev(handle);\n	struct acpi_device_physical_node *pn;\n	bool second_pass = (bool)data;\n	acpi_status status = AE_OK;\n\n	if (!device)\n		return AE_OK;\n\n	if (device->handler && !device->handler->hotplug.enabled) {\n		*ret_p = &device->dev;\n		return AE_SUPPORT;\n	}\n\n	mutex_lock(&device->physical_node_lock);\n\n	list_for_each_entry(pn, &device->physical_node_list, node) {\n		int ret;\n\n		if (second_pass) {\n			/* Skip devices offlined by the first pass. */\n			if (pn->put_online)\n				continue;\n		} else {\n			pn->put_online = false;\n		}\n		ret = device_offline(pn->dev);\n		if (ret >= 0) {\n			pn->put_online = !ret;\n		} else {\n			*ret_p = pn->dev;\n			if (second_pass) {\n				status = AE_ERROR;\n				break;\n			}\n		}\n	}\n\n	mutex_unlock(&device->physical_node_lock);\n\n	return status;\n}\n\nstatic acpi_status acpi_bus_online(acpi_handle handle, u32 lvl, void *data,\n				   void **ret_p)\n{\n	struct acpi_device *device = acpi_fetch_acpi_dev(handle);\n	struct acpi_device_physical_node *pn;\n\n	if (!device)\n		return AE_OK;\n\n	mutex_lock(&device->physical_node_lock);\n\n	list_for_each_entry(pn, &device->physical_node_list, node)\n		if (pn->put_online) {\n			device_online(pn->dev);\n			pn->put_online = false;\n		}\n\n	mutex_unlock(&device->physical_node_lock);\n\n	return AE_OK;\n}\n\nstatic int acpi_scan_try_to_offline(struct acpi_device *device)\n{\n	acpi_handle handle = device->handle;\n	struct device *errdev = NULL;\n	acpi_status status;\n\n	/*\n	 * Carry out two passes here and ignore errors in the first pass,\n	 * because if the devices in question are memory blocks and\n	 * CONFIG_MEMCG is set, one of the blocks may hold data structures\n	 * that the other blocks depend on, but it is not known in advance which\n	 * block holds them.\n	 *\n	 * If the first pass is successful, the second one isn't needed, though.\n	 */\n	status = acpi_walk_namespace(ACPI_TYPE_ANY, handle, ACPI_UINT32_MAX,\n				     NULL, acpi_bus_offline, (void *)false,\n				     (void **)&errdev);\n	if (status == AE_SUPPORT) {\n		dev_warn(errdev, \"Offline disabled.\\n\");\n		acpi_walk_namespace(ACPI_TYPE_ANY, handle, ACPI_UINT32_MAX,\n				    acpi_bus_online, NULL, NULL, NULL);\n		return -EPERM;\n	}\n	acpi_bus_offline(handle, 0, (void *)false, (void **)&errdev);\n	if (errdev) {\n		errdev = NULL;\n		acpi_walk_namespace(ACPI_TYPE_ANY, handle, ACPI_UINT32_MAX,\n				    NULL, acpi_bus_offline, (void *)true,\n				    (void **)&errdev);\n		if (!errdev)\n			acpi_bus_offline(handle, 0, (void *)true,\n					 (void **)&errdev);\n\n		if (errdev) {\n			dev_warn(errdev, \"Offline failed.\\n\");\n			acpi_bus_online(handle, 0, NULL, NULL);\n			acpi_walk_namespace(ACPI_TYPE_ANY, handle,\n					    ACPI_UINT32_MAX, acpi_bus_online,\n					    NULL, NULL, NULL);\n			return -EBUSY;\n		}\n	}\n	return 0;\n}\n\n#define ACPI_SCAN_CHECK_FLAG_STATUS	BIT(0)\n#define ACPI_SCAN_CHECK_FLAG_EJECT	BIT(1)\n\nstatic int acpi_scan_check_and_detach(struct acpi_device *adev, void *p)\n{\n	struct acpi_scan_handler *handler = adev->handler;\n	uintptr_t flags = (uintptr_t)p;\n\n	acpi_dev_for_each_child_reverse(adev, acpi_scan_check_and_detach, p);\n\n	if (flags & ACPI_SCAN_CHECK_FLAG_STATUS) {\n		acpi_bus_get_status(adev);\n		/*\n		 * Skip devices that are still there and take the enabled\n		 * flag into account.\n		 */\n		if (acpi_device_is_enabled(adev))\n			return 0;\n\n		/* Skip device that have not been enumerated. */\n		if (!acpi_device_enumerated(adev)) {\n			dev_dbg(&adev->dev, \"Still not enumerated\\n\");\n			return 0;\n		}\n	}\n\n	if (handler && handler->detach)\n		handler->detach(adev);\n\n	/*\n	 * Most likely, the device is going away, so put it into D3cold before\n	 * that.\n	 */\n	acpi_device_set_power(adev, ACPI_STATE_D3_COLD);\n	adev->flags.initialized = false;\n\n	/* For eject this is deferred to acpi_bus_post_eject() */\n	if (!(flags & ACPI_SCAN_CHECK_FLAG_EJECT)) {\n		adev->handler = NULL;\n		acpi_device_clear_enumerated(adev);\n	}\n	return 0;\n}\n\nstatic int acpi_bus_post_eject(struct acpi_device *adev, void *not_used)\n{\n	struct acpi_scan_handler *handler = adev->handler;\n\n	acpi_dev_for_each_child_reverse(adev, acpi_bus_post_eject, NULL);\n\n	if (handler) {\n		if (handler->post_eject)\n			handler->post_eject(adev);\n\n		adev->handler = NULL;\n	}\n\n	acpi_device_clear_enumerated(adev);\n\n	return 0;\n}\n\nstatic void acpi_scan_check_subtree(struct acpi_device *adev)\n{\n	uintptr_t flags = ACPI_SCAN_CHECK_FLAG_STATUS;\n\n	acpi_scan_check_and_detach(adev, (void *)flags);\n}\n\nstatic int acpi_scan_hot_remove(struct acpi_device *device)\n{\n	acpi_handle handle = device->handle;\n	unsigned long long sta;\n	acpi_status status;\n	uintptr_t flags = ACPI_SCAN_CHECK_FLAG_EJECT;\n\n	if (device->handler && device->handler->hotplug.demand_offline) {\n		if (!acpi_scan_is_offline(device, true))\n			return -EBUSY;\n	} else {\n		int error = acpi_scan_try_to_offline(device);\n		if (error)\n			return error;\n	}\n\n	acpi_handle_debug(handle, \"Ejecting\\n\");\n\n	acpi_scan_check_and_detach(device, (void *)flags);\n\n	acpi_evaluate_lck(handle, 0);\n	/*\n	 * TBD: _EJD support.\n	 */\n	status = acpi_evaluate_ej0(handle);\n	if (status == AE_NOT_FOUND)\n		return -ENODEV;\n	else if (ACPI_FAILURE(status))\n		return -EIO;\n\n	/*\n	 * Verify if eject was indeed successful.  If not, log an error\n	 * message.  No need to call _OST since _EJ0 call was made OK.\n	 */\n	status = acpi_evaluate_integer(handle, \"_STA\", NULL, &sta);\n	if (ACPI_FAILURE(status)) {\n		acpi_handle_warn(handle,\n			\"Status check after eject failed (0x%x)\\n\", status);\n	} else if (sta & ACPI_STA_DEVICE_ENABLED) {\n		acpi_handle_warn(handle,\n			\"Eject incomplete - status 0x%llx\\n\", sta);\n	} else {\n		acpi_bus_post_eject(device, NULL);\n	}\n\n	return 0;\n}\n\nstatic int acpi_scan_rescan_bus(struct acpi_device *adev)\n{\n	struct acpi_scan_handler *handler = adev->handler;\n	int ret;\n\n	if (handler && handler->hotplug.scan_dependent)\n		ret = handler->hotplug.scan_dependent(adev);\n	else\n		ret = acpi_bus_scan(adev->handle);\n\n	if (ret)\n		dev_info(&adev->dev, \"Namespace scan failure\\n\");\n\n	return ret;\n}\n\nstatic int acpi_scan_device_check(struct acpi_device *adev)\n{\n	struct acpi_device *parent;\n\n	acpi_scan_check_subtree(adev);\n\n	if (!acpi_device_is_present(adev))\n		return 0;\n\n	/*\n	 * This function is only called for device objects for which matching\n	 * scan handlers exist.  The only situation in which the scan handler\n	 * is not attached to this device object yet is when the device has\n	 * just appeared (either it wasn't present at all before or it was\n	 * removed and then added again).\n	 */\n	if (adev->handler) {\n		dev_dbg(&adev->dev, \"Already enumerated\\n\");\n		return 0;\n	}\n\n	parent = acpi_dev_parent(adev);\n	if (!parent)\n		parent = adev;\n\n	return acpi_scan_rescan_bus(parent);\n}\n\nstatic int acpi_scan_bus_check(struct acpi_device *adev)\n{\n	acpi_scan_check_subtree(adev);\n\n	return acpi_scan_rescan_bus(adev);\n}\n\nstatic int acpi_generic_hotplug_event(struct acpi_device *adev, u32 type)\n{\n	switch (type) {\n	case ACPI_NOTIFY_BUS_CHECK:\n		return acpi_scan_bus_check(adev);\n	case ACPI_NOTIFY_DEVICE_CHECK:\n		return acpi_scan_device_check(adev);\n	case ACPI_NOTIFY_EJECT_REQUEST:\n	case ACPI_OST_EC_OSPM_EJECT:\n		if (adev->handler && !adev->handler->hotplug.enabled) {\n			dev_info(&adev->dev, \"Eject disabled\\n\");\n			return -EPERM;\n		}\n		acpi_evaluate_ost(adev->handle, ACPI_NOTIFY_EJECT_REQUEST,\n				  ACPI_OST_SC_EJECT_IN_PROGRESS, NULL);\n		return acpi_scan_hot_remove(adev);\n	}\n	return -EINVAL;\n}\n\nvoid acpi_device_hotplug(struct acpi_device *adev, u32 src)\n{\n	u32 ost_code = ACPI_OST_SC_NON_SPECIFIC_FAILURE;\n	int error = -ENODEV;\n\n	lock_device_hotplug();\n	mutex_lock(&acpi_scan_lock);\n\n	/*\n	 * The device object's ACPI handle cannot become invalid as long as we\n	 * are holding acpi_scan_lock, but it might have become invalid before\n	 * that lock was acquired.\n	 */\n	if (adev->handle == INVALID_ACPI_HANDLE)\n		goto err_out;\n\n	if (adev->flags.is_dock_station) {\n		error = dock_notify(adev, src);\n	} else if (adev->flags.hotplug_notify) {\n		error = acpi_generic_hotplug_event(adev, src);\n	} else {\n		acpi_hp_notify notify;\n\n		acpi_lock_hp_context();\n		notify = adev->hp ? adev->hp->notify : NULL;\n		acpi_unlock_hp_context();\n		/*\n		 * There may be additional notify handlers for device objects\n		 * without the .event() callback, so ignore them here.\n		 */\n		if (notify)\n			error = notify(adev, src);\n		else\n			goto out;\n	}\n	switch (error) {\n	case 0:\n		ost_code = ACPI_OST_SC_SUCCESS;\n		break;\n	case -EPERM:\n		ost_code = ACPI_OST_SC_EJECT_NOT_SUPPORTED;\n		break;\n	case -EBUSY:\n		ost_code = ACPI_OST_SC_DEVICE_BUSY;\n		break;\n	default:\n		ost_code = ACPI_OST_SC_NON_SPECIFIC_FAILURE;\n		break;\n	}\n\n err_out:\n	acpi_evaluate_ost(adev->handle, src, ost_code, NULL);\n\n out:\n	acpi_put_acpi_dev(adev);\n	mutex_unlock(&acpi_scan_lock);\n	unlock_device_hotplug();\n}\n\nstatic void acpi_free_power_resources_lists(struct acpi_device *device)\n{\n	int i;\n\n	if (device->wakeup.flags.valid)\n		acpi_power_resources_list_free(&device->wakeup.resources);\n\n	if (!device->power.flags.power_resources)\n		return;\n\n	for (i = ACPI_STATE_D0; i <= ACPI_STATE_D3_HOT; i++) {\n		struct acpi_device_power_state *ps = &device->power.states[i];\n		acpi_power_resources_list_free(&ps->resources);\n	}\n}\n\nstatic void acpi_device_release(struct device *dev)\n{\n	struct acpi_device *acpi_dev = to_acpi_device(dev);\n\n	acpi_free_properties(acpi_dev);\n	acpi_free_pnp_ids(&acpi_dev->pnp);\n	acpi_free_power_resources_lists(acpi_dev);\n	kfree(acpi_dev);\n}\n\nstatic void acpi_device_cleanup(struct acpi_device *device)\n{\n	struct acpi_device_bus_id *acpi_device_bus_id;\n\n	list_for_each_entry(acpi_device_bus_id, &acpi_bus_id_list, node)\n		if (!strcmp(acpi_device_bus_id->bus_id,\n			    acpi_device_hid(device))) {\n			ida_free(&acpi_device_bus_id->instance_ida,\n				 device->pnp.instance_no);\n			if (ida_is_empty(&acpi_device_bus_id->instance_ida)) {\n				list_del(&acpi_device_bus_id->node);\n				kfree_const(acpi_device_bus_id->bus_id);\n				kfree(acpi_device_bus_id);\n			}\n			break;\n		}\n\n	list_del(&device->wakeup_list);\n}\n\nstatic void acpi_device_del(struct acpi_device *device)\n{\n	mutex_lock(&acpi_device_lock);\n\n	acpi_device_cleanup(device);\n\n	mutex_unlock(&acpi_device_lock);\n\n	acpi_power_add_remove_device(device, false);\n	acpi_device_remove_files(device);\n	if (device->remove)\n		device->remove(device);\n\n	device_del(&device->dev);\n}\n\nstatic BLOCKING_NOTIFIER_HEAD(acpi_reconfig_chain);\n\nstatic LIST_HEAD(acpi_device_del_list);\nstatic DEFINE_MUTEX(acpi_device_del_lock);\n\nstatic void acpi_device_del_work_fn(struct work_struct *work_not_used)\n{\n	for (;;) {\n		struct acpi_device *adev;\n\n		mutex_lock(&acpi_device_del_lock);\n\n		if (list_empty(&acpi_device_del_list)) {\n			mutex_unlock(&acpi_device_del_lock);\n			break;\n		}\n		adev = list_first_entry(&acpi_device_del_list,\n					struct acpi_device, del_list);\n		list_del(&adev->del_list);\n\n		mutex_unlock(&acpi_device_del_lock);\n\n		blocking_notifier_call_chain(&acpi_reconfig_chain,\n					     ACPI_RECONFIG_DEVICE_REMOVE, adev);\n\n		acpi_device_del(adev);\n		/*\n		 * Drop references to all power resources that might have been\n		 * used by the device.\n		 */\n		acpi_power_transition(adev, ACPI_STATE_D3_COLD);\n		acpi_dev_put(adev);\n	}\n}\n\n/**\n * acpi_scan_drop_device - Drop an ACPI device object.\n * @handle: Handle of an ACPI namespace node, not used.\n * @context: Address of the ACPI device object to drop.\n *\n * This is invoked by acpi_ns_delete_node() during the removal of the ACPI\n * namespace node the device object pointed to by @context is attached to.\n *\n * The unregistration is carried out asynchronously to avoid running\n * acpi_device_del() under the ACPICA's namespace mutex and the list is used to\n * ensure the correct ordering (the device objects must be unregistered in the\n * same order in which the corresponding namespace nodes are deleted).\n */\nstatic void acpi_scan_drop_device(acpi_handle handle, void *context)\n{\n	static DECLARE_WORK(work, acpi_device_del_work_fn);\n	struct acpi_device *adev = context;\n\n	mutex_lock(&acpi_device_del_lock);\n\n	/*\n	 * Use the ACPI hotplug workqueue which is ordered, so this work item\n	 * won't run after any hotplug work items submitted subsequently.  That\n	 * prevents attempts to register device objects identical to those being\n	 * deleted from happening concurrently (such attempts result from\n	 * hotplug events handled via the ACPI hotplug workqueue).  It also will\n	 * run after all of the work items submitted previously, which helps\n	 * those work items to ensure that they are not accessing stale device\n	 * objects.\n	 */\n	if (list_empty(&acpi_device_del_list))\n		acpi_queue_hotplug_work(&work);\n\n	list_add_tail(&adev->del_list, &acpi_device_del_list);\n	/* Make acpi_ns_validate_handle() return NULL for this handle. */\n	adev->handle = INVALID_ACPI_HANDLE;\n\n	mutex_unlock(&acpi_device_del_lock);\n}\n\nstatic struct acpi_device *handle_to_device(acpi_handle handle,\n					    void (*callback)(void *))\n{\n	struct acpi_device *adev = NULL;\n	acpi_status status;\n\n	status = acpi_get_data_full(handle, acpi_scan_drop_device,\n				    (void **)&adev, callback);\n	if (ACPI_FAILURE(status) || !adev) {\n		acpi_handle_debug(handle, \"No context!\\n\");\n		return NULL;\n	}\n	return adev;\n}\n\n/**\n * acpi_fetch_acpi_dev - Retrieve ACPI device object.\n * @handle: ACPI handle associated with the requested ACPI device object.\n *\n * Return a pointer to the ACPI device object associated with @handle, if\n * present, or NULL otherwise.\n */\nstruct acpi_device *acpi_fetch_acpi_dev(acpi_handle handle)\n{\n	return handle_to_device(handle, NULL);\n}\nEXPORT_SYMBOL_GPL(acpi_fetch_acpi_dev);\n\nstatic void get_acpi_device(void *dev)\n{\n	acpi_dev_get(dev);\n}\n\n/**\n * acpi_get_acpi_dev - Retrieve ACPI device object and reference count it.\n * @handle: ACPI handle associated with the requested ACPI device object.\n *\n * Return a pointer to the ACPI device object associated with @handle and bump\n * up that object's reference counter (under the ACPI Namespace lock), if\n * present, or return NULL otherwise.\n *\n * The ACPI device object reference acquired by this function needs to be\n * dropped via acpi_dev_put().\n */\nstruct acpi_device *acpi_get_acpi_dev(acpi_handle handle)\n{\n	return handle_to_device(handle, get_acpi_device);\n}\nEXPORT_SYMBOL_GPL(acpi_get_acpi_dev);\n\nstatic struct acpi_device_bus_id *acpi_device_bus_id_match(const char *dev_id)\n{\n	struct acpi_device_bus_id *acpi_device_bus_id;\n\n	/* Find suitable bus_id and instance number in acpi_bus_id_list. */\n	list_for_each_entry(acpi_device_bus_id, &acpi_bus_id_list, node) {\n		if (!strcmp(acpi_device_bus_id->bus_id, dev_id))\n			return acpi_device_bus_id;\n	}\n	return NULL;\n}\n\nstatic int acpi_device_set_name(struct acpi_device *device,\n				struct acpi_device_bus_id *acpi_device_bus_id)\n{\n	struct ida *instance_ida = &acpi_device_bus_id->instance_ida;\n	int result;\n\n	result = ida_alloc(instance_ida, GFP_KERNEL);\n	if (result < 0)\n		return result;\n\n	device->pnp.instance_no = result;\n	dev_set_name(&device->dev, \"%s:%02x\", acpi_device_bus_id->bus_id, result);\n	return 0;\n}\n\nint acpi_tie_acpi_dev(struct acpi_device *adev)\n{\n	acpi_handle handle = adev->handle;\n	acpi_status status;\n\n	if (!handle)\n		return 0;\n\n	status = acpi_attach_data(handle, acpi_scan_drop_device, adev);\n	if (ACPI_FAILURE(status)) {\n		acpi_handle_err(handle, \"Unable to attach device data\\n\");\n		return -ENODEV;\n	}\n\n	return 0;\n}\n\nstatic void acpi_store_pld_crc(struct acpi_device *adev)\n{\n	struct acpi_pld_info *pld;\n\n	if (!acpi_get_physical_device_location(adev->handle, &pld))\n		return;\n\n	adev->pld_crc = crc32(~0, pld, sizeof(*pld));\n	ACPI_FREE(pld);\n}\n\nint acpi_device_add(struct acpi_device *device)\n{\n	struct acpi_device_bus_id *acpi_device_bus_id;\n	int result;\n\n	/*\n	 * Linkage\n	 * -------\n	 * Link this device to its parent and siblings.\n	 */\n	INIT_LIST_HEAD(&device->wakeup_list);\n	INIT_LIST_HEAD(&device->physical_node_list);\n	INIT_LIST_HEAD(&device->del_list);\n	mutex_init(&device->physical_node_lock);\n\n	mutex_lock(&acpi_device_lock);\n\n	acpi_device_bus_id = acpi_device_bus_id_match(acpi_device_hid(device));\n	if (acpi_device_bus_id) {\n		result = acpi_device_set_name(device, acpi_device_bus_id);\n		if (result)\n			goto err_unlock;\n	} else {\n		acpi_device_bus_id = kzalloc_obj(*acpi_device_bus_id);\n		if (!acpi_device_bus_id) {\n			result = -ENOMEM;\n			goto err_unlock;\n		}\n		acpi_device_bus_id->bus_id =\n			kstrdup_const(acpi_device_hid(device), GFP_KERNEL);\n		if (!acpi_device_bus_id->bus_id) {\n			kfree(acpi_device_bus_id);\n			result = -ENOMEM;\n			goto err_unlock;\n		}\n\n		ida_init(&acpi_device_bus_id->instance_ida);\n\n		result = acpi_device_set_name(device, acpi_device_bus_id);\n		if (result) {\n			kfree_const(acpi_device_bus_id->bus_id);\n			kfree(acpi_device_bus_id);\n			goto err_unlock;\n		}\n\n		list_add_tail(&acpi_device_bus_id->node, &acpi_bus_id_list);\n	}\n\n	if (device->wakeup.flags.valid)\n		list_add_tail(&device->wakeup_list, &acpi_wakeup_device_list);\n\n	acpi_store_pld_crc(device);\n\n	mutex_unlock(&acpi_device_lock);\n\n	result = device_add(&device->dev);\n	if (result) {\n		dev_err(&device->dev, \"Error registering device\\n\");\n		goto err;\n	}\n\n	acpi_device_setup_files(device);\n\n	return 0;\n\nerr:\n	mutex_lock(&acpi_device_lock);\n\n	acpi_device_cleanup(device);\n\nerr_unlock:\n	mutex_unlock(&acpi_device_lock);\n\n	acpi_detach_data(device->handle, acpi_scan_drop_device);\n\n	return result;\n}\n\n/* --------------------------------------------------------------------------\n                                 Device Enumeration\n   -------------------------------------------------------------------------- */\nstatic bool acpi_info_matches_ids(struct acpi_device_info *info,\n				  const char * const ids[])\n{\n	struct acpi_pnp_device_id_list *cid_list = NULL;\n	int i, index;\n\n	if (!(info->valid & ACPI_VALID_HID))\n		return false;\n\n	index = match_string(ids, -1, info->hardware_id.string);\n	if (index >= 0)\n		return true;\n\n	if (info->valid & ACPI_VALID_CID)\n		cid_list = &info->compatible_id_list;\n\n	if (!cid_list)\n		return false;\n\n	for (i = 0; i < cid_list->count; i++) {\n		index = match_string(ids, -1, cid_list->ids[i].string);\n		if (index >= 0)\n			return true;\n	}\n\n	return false;\n}\n\n/* List of HIDs for which we ignore matching ACPI devices, when checking _DEP lists. */\nstatic const char * const acpi_ignore_dep_ids[] = {\n	\"PNP0D80\", /* Windows-compatible System Power Management Controller */\n	\"INT33BD\", /* Intel Baytrail Mailbox Device */\n	\"LATT2021\", /* Lattice FW Update Client Driver */\n	NULL\n};\n\n/* List of HIDs for which we honor deps of matching ACPI devs, when checking _DEP lists. */\nstatic const char * const acpi_honor_dep_ids[] = {\n	\"ARMH0003\", /* ARM GICv5 IWB */\n	\"INT3472\", /* Camera sensor PMIC / clk and regulator info */\n	\"INTC1059\", /* IVSC (TGL) driver must be loaded to allow i2c access to camera sensors */\n	\"INTC1095\", /* IVSC (ADL) driver must be loaded to allow i2c access to camera sensors */\n	\"INTC100A\", /* IVSC (RPL) driver must be loaded to allow i2c access to camera sensors */\n	\"INTC10CF\", /* IVSC (MTL) driver must be loaded to allow i2c access to camera sensors */\n	\"INTC10DE\", /* CVS (LNL) driver must be loaded to allow camera streaming */\n	\"INTC10E0\", /* CVS (ARL) driver must be loaded to allow camera streaming */\n	\"INTC10E1\", /* CVS (PTL) driver must be loaded to allow camera streaming */\n	\"INTC10FA\", /* CVS (NVL) driver must be loaded to allow camera streaming */\n	\"RSCV0001\", /* RISC-V PLIC */\n	\"RSCV0002\", /* RISC-V APLIC */\n	\"RSCV0005\", /* RISC-V SBI MPXY MBOX */\n	\"RSCV0006\", /* RISC-V RPMI SYSMSI */\n	\"PNP0C0F\",  /* PCI Link Device */\n	\"ACPI0016\", /* CXL/PCIe host bridge: CXL root (ACPI0017) depends on PCI root attach */\n	NULL\n};\n\nstatic struct acpi_device *acpi_find_parent_acpi_dev(acpi_handle handle)\n{\n	struct acpi_device *adev;\n\n	/*\n	 * Fixed hardware devices do not appear in the namespace and do not\n	 * have handles, but we fabricate acpi_devices for them, so we have\n	 * to deal with them specially.\n	 */\n	if (!handle)\n		return acpi_root;\n\n	do {\n		acpi_status status;\n\n		status = acpi_get_parent(handle, &handle);\n		if (ACPI_FAILURE(status)) {\n			if (status != AE_NULL_ENTRY)\n				return acpi_root;\n\n			return NULL;\n		}\n		adev = acpi_fetch_acpi_dev(handle);\n	} while (!adev);\n	return adev;\n}\n\nacpi_status\nacpi_bus_get_ejd(acpi_handle handle, acpi_handle *ejd)\n{\n	acpi_status status;\n	acpi_handle tmp;\n	struct acpi_buffer buffer = {ACPI_ALLOCATE_BUFFER, NULL};\n	union acpi_object *obj;\n\n	status = acpi_get_handle(handle, \"_EJD\", &tmp);\n	if (ACPI_FAILURE(status))\n		return status;\n\n	status = acpi_evaluate_object(handle, \"_EJD\", NULL, &buffer);\n	if (ACPI_SUCCESS(status)) {\n		obj = buffer.pointer;\n		status = acpi_get_handle(ACPI_ROOT_OBJECT, obj->string.pointer,\n					 ejd);\n		kfree(buffer.pointer);\n	}\n	return status;\n}\nEXPORT_SYMBOL_GPL(acpi_bus_get_ejd);\n\nstatic int acpi_bus_extract_wakeup_device_power_package(struct acpi_device *dev)\n{\n	acpi_handle handle = dev->handle;\n	struct acpi_device_wakeup *wakeup = &dev->wakeup;\n	struct acpi_buffer buffer = { ACPI_ALLOCATE_BUFFER, NULL };\n	union acpi_object *package = NULL;\n	union acpi_object *element = NULL;\n	acpi_status status;\n	int err = -ENODATA;\n\n	INIT_LIST_HEAD(&wakeup->resources);\n\n	/* _PRW */\n	status = acpi_evaluate_object(handle, \"_PRW\", NULL, &buffer);\n	if (ACPI_FAILURE(status)) {\n		acpi_handle_info(handle, \"_PRW evaluation failed: %s\\n\",\n				 acpi_format_exception(status));\n		return err;\n	}\n\n	package = (union acpi_object *)buffer.pointer;\n\n	if (!package || package->package.count < 2)\n		goto out;\n\n	element = &(package->package.elements[0]);\n	if (!element)\n		goto out;\n\n	if (element->type == ACPI_TYPE_PACKAGE) {\n		if ((element->package.count < 2) ||\n		    (element->package.elements[0].type !=\n		     ACPI_TYPE_LOCAL_REFERENCE)\n		    || (element->package.elements[1].type != ACPI_TYPE_INTEGER))\n			goto out;\n\n		wakeup->gpe_device =\n		    element->package.elements[0].reference.handle;\n		wakeup->gpe_number =\n		    (u32) element->package.elements[1].integer.value;\n	} else if (element->type == ACPI_TYPE_INTEGER) {\n		wakeup->gpe_device = NULL;\n		wakeup->gpe_number = element->integer.value;\n	} else {\n		goto out;\n	}\n\n	element = &(package->package.elements[1]);\n	if (element->type != ACPI_TYPE_INTEGER)\n		goto out;\n\n	wakeup->sleep_state = element->integer.value;\n\n	err = acpi_extract_power_resources(package, 2, &wakeup->resources);\n	if (err)\n		goto out;\n\n	if (!list_empty(&wakeup->resources)) {\n		int sleep_state;\n\n		err = acpi_power_wakeup_list_init(&wakeup->resources,\n						  &sleep_state);\n		if (err) {\n			acpi_handle_warn(handle, \"Retrieving current states \"\n					 \"of wakeup power resources failed\\n\");\n			acpi_power_resources_list_free(&wakeup->resources);\n			goto out;\n		}\n		if (sleep_state < wakeup->sleep_state) {\n			acpi_handle_warn(handle, \"Overriding _PRW sleep state \"\n					 \"(S%d) by S%d from power resources\\n\",\n					 (int)wakeup->sleep_state, sleep_state);\n			wakeup->sleep_state = sleep_state;\n		}\n	}\n\n out:\n	kfree(buffer.pointer);\n	return err;\n}\n\nstatic bool acpi_wakeup_gpe_init(struct acpi_device *device)\n{\n	static const struct acpi_device_id button_device_ids[] = {\n		{\"PNP0C0D\", 0},	/* Lid */\n		{\"PNP0C0E\", 0},	/* Sleep button */\n		{\"\", 0},\n	};\n	struct acpi_device_wakeup *wakeup = &device->wakeup;\n	const struct acpi_device_id *match;\n	acpi_status status;\n\n	wakeup->flags.notifier_present = 0;\n\n	match = acpi_match_acpi_device(button_device_ids, device);\n	if (match && wakeup->sleep_state == ACPI_STATE_S5)\n		wakeup->sleep_state = ACPI_STATE_S4;\n\n	status = acpi_setup_gpe_for_wake(device->handle, wakeup->gpe_device,\n					 wakeup->gpe_number);\n	return ACPI_SUCCESS(status);\n}\n\nstatic void acpi_bus_get_wakeup_device_flags(struct acpi_device *device)\n{\n	int err;\n\n	/* Presence of _PRW indicates wake capable */\n	if (!acpi_has_method(device->handle, \"_PRW\"))\n		return;\n\n	err = acpi_bus_extract_wakeup_device_power_package(device);\n	if (err) {\n		dev_err(&device->dev, \"Unable to extract wakeup power resources\");\n		return;\n	}\n\n	device->wakeup.flags.valid = acpi_wakeup_gpe_init(device);\n	device->wakeup.prepare_count = 0;\n	/*\n	 * Call _PSW/_DSW object to disable its ability to wake the sleeping\n	 * system for the ACPI device with the _PRW object.\n	 * The _PSW object is deprecated in ACPI 3.0 and is replaced by _DSW.\n	 * So it is necessary to call _DSW object first. Only when it is not\n	 * present will the _PSW object used.\n	 */\n	err = acpi_device_sleep_wake(device, 0, 0, 0);\n	if (err)\n		pr_debug(\"error in _DSW or _PSW evaluation\\n\");\n}\n\nstatic void acpi_bus_init_power_state(struct acpi_device *device, int state)\n{\n	struct acpi_device_power_state *ps = &device->power.states[state];\n	char pathname[5] = { '_', 'P', 'R', '0' + state, '\\0' };\n	struct acpi_buffer buffer = { ACPI_ALLOCATE_BUFFER, NULL };\n	acpi_status status;\n\n	INIT_LIST_HEAD(&ps->resources);\n\n	/* Evaluate \"_PRx\" to get referenced power resources */\n	status = acpi_evaluate_object(device->handle, pathname, NULL, &buffer);\n	if (ACPI_SUCCESS(status)) {\n		union acpi_object *package = buffer.pointer;\n\n		if (buffer.length && package\n		    && package->type == ACPI_TYPE_PACKAGE\n		    && package->package.count)\n			acpi_extract_power_resources(package, 0, &ps->resources);\n\n		ACPI_FREE(buffer.pointer);\n	}\n\n	/* Evaluate \"_PSx\" to see if we can do explicit sets */\n	pathname[2] = 'S';\n	if (acpi_has_method(device->handle, pathname))\n		ps->flags.explicit_set = 1;\n\n	/* State is valid if there are means to put the device into it. */\n	if (!list_empty(&ps->resources) || ps->flags.explicit_set)\n		ps->flags.valid = 1;\n\n	ps->power = -1;		/* Unknown - driver assigned */\n	ps->latency = -1;	/* Unknown - driver assigned */\n}\n\nstatic void acpi_bus_get_power_flags(struct acpi_device *device)\n{\n	unsigned long long dsc = ACPI_STATE_D0;\n	u32 i;\n\n	/* Presence of _PS0|_PR0 indicates 'power manageable' */\n	if (!acpi_has_method(device->handle, \"_PS0\") &&\n	    !acpi_has_method(device->handle, \"_PR0\"))\n		return;\n\n	device->flags.power_manageable = 1;\n\n	/*\n	 * Power Management Flags\n	 */\n	if (acpi_has_method(device->handle, \"_PSC\"))\n		device->power.flags.explicit_get = 1;\n\n	if (acpi_has_method(device->handle, \"_IRC\"))\n		device->power.flags.inrush_current = 1;\n\n	if (acpi_has_method(device->handle, \"_DSW\"))\n		device->power.flags.dsw_present = 1;\n\n	acpi_evaluate_integer(device->handle, \"_DSC\", NULL, &dsc);\n	device->power.state_for_enumeration = dsc;\n\n	/*\n	 * Enumerate supported power management states\n	 */\n	for (i = ACPI_STATE_D0; i <= ACPI_STATE_D3_HOT; i++)\n		acpi_bus_init_power_state(device, i);\n\n	INIT_LIST_HEAD(&device->power.states[ACPI_STATE_D3_COLD].resources);\n\n	/* Set the defaults for D0 and D3hot (always supported). */\n	device->power.states[ACPI_STATE_D0].flags.valid = 1;\n	device->power.states[ACPI_STATE_D0].power = 100;\n	device->power.states[ACPI_STATE_D3_HOT].flags.valid = 1;\n\n	/*\n	 * Use power resources only if the D0 list of them is populated, because\n	 * some platforms may provide _PR3 only to indicate D3cold support and\n	 * in those cases the power resources list returned by it may be bogus.\n	 */\n	if (!list_empty(&device->power.states[ACPI_STATE_D0].resources)) {\n		device->power.flags.power_resources = 1;\n		/*\n		 * D3cold is supported if the D3hot list of power resources is\n		 * not empty.\n		 */\n		if (!list_empty(&device->power.states[ACPI_STATE_D3_HOT].resources))\n			device->power.states[ACPI_STATE_D3_COLD].flags.valid = 1;\n	}\n\n	if (acpi_bus_init_power(device))\n		device->flags.power_manageable = 0;\n}\n\nstatic void acpi_bus_get_flags(struct acpi_device *device)\n{\n	/* Presence of _STA indicates 'dynamic_status' */\n	if (acpi_has_method(device->handle, \"_STA\"))\n		device->flags.dynamic_status = 1;\n\n	/* Presence of _RMV indicates 'removable' */\n	if (acpi_has_method(device->handle, \"_RMV\"))\n		device->flags.removable = 1;\n\n	/* Presence of _EJD|_EJ0 indicates 'ejectable' */\n	if (acpi_has_method(device->handle, \"_EJD\") ||\n	    acpi_has_method(device->handle, \"_EJ0\"))\n		device->flags.ejectable = 1;\n}\n\nstatic void acpi_device_get_busid(struct acpi_device *device)\n{\n	char bus_id[5] = { '?', 0 };\n	struct acpi_buffer buffer = { sizeof(bus_id), bus_id };\n	int i = 0;\n\n	/*\n	 * Bus ID\n	 * ------\n	 * The device's Bus ID is simply the object name.\n	 * TBD: Shouldn't this value be unique (within the ACPI namespace)?\n	 */\n	if (!acpi_dev_parent(device)) {\n		strscpy(device->pnp.bus_id, \"ACPI\");\n		return;\n	}\n\n	switch (device->device_type) {\n	case ACPI_BUS_TYPE_POWER_BUTTON:\n		strscpy(device->pnp.bus_id, \"PWRF\");\n		break;\n	case ACPI_BUS_TYPE_SLEEP_BUTTON:\n		strscpy(device->pnp.bus_id, \"SLPF\");\n		break;\n	case ACPI_BUS_TYPE_ECDT_EC:\n		strscpy(device->pnp.bus_id, \"ECDT\");\n		break;\n	default:\n		acpi_get_name(device->handle, ACPI_SINGLE_NAME, &buffer);\n		/* Clean up trailing underscores (if any) */\n		for (i = 3; i > 1; i--) {\n			if (bus_id[i] == '_')\n				bus_id[i] = '\\0';\n			else\n				break;\n		}\n		strscpy(device->pnp.bus_id, bus_id);\n		break;\n	}\n}\n\n/*\n * acpi_ata_match - see if an acpi object is an ATA device\n *\n * If an acpi object has one of the ACPI ATA methods defined,\n * then we can safely call it an ATA device.\n */\nbool acpi_ata_match(acpi_handle handle)\n{\n	return acpi_has_method(handle, \"_GTF\") ||\n	       acpi_has_method(handle, \"_GTM\") ||\n	       acpi_has_method(handle, \"_STM\") ||\n	       acpi_has_method(handle, \"_SDD\");\n}\n\n/*\n * acpi_bay_match - see if an acpi object is an ejectable driver bay\n *\n * If an acpi object is ejectable and has one of the ACPI ATA methods defined,\n * then we can safely call it an ejectable drive bay\n */\nbool acpi_bay_match(acpi_handle handle)\n{\n	acpi_handle phandle;\n\n	if (!acpi_has_method(handle, \"_EJ0\"))\n		return false;\n	if (acpi_ata_match(handle))\n		return true;\n	if (ACPI_FAILURE(acpi_get_parent(handle, &phandle)))\n		return false;\n\n	return acpi_ata_match(phandle);\n}\n\nbool acpi_device_is_battery(struct acpi_device *adev)\n{\n	struct acpi_hardware_id *hwid;\n\n	list_for_each_entry(hwid, &adev->pnp.ids, list)\n		if (!strcmp(\"PNP0C0A\", hwid->id))\n			return true;\n\n	return false;\n}\n\nstatic bool is_ejectable_bay(struct acpi_device *adev)\n{\n	acpi_handle handle = adev->handle;\n\n	if (acpi_has_method(handle, \"_EJ0\") && acpi_device_is_battery(adev))\n		return true;\n\n	return acpi_bay_match(handle);\n}\n\n/*\n * acpi_dock_match - see if an acpi object has a _DCK method\n */\nbool acpi_dock_match(acpi_handle handle)\n{\n	return acpi_has_method(handle, \"_DCK\");\n}\n\nstatic acpi_status\nacpi_backlight_cap_match(acpi_handle handle, u32 level, void *context,\n			  void **return_value)\n{\n	long *cap = context;\n\n	if (acpi_has_method(handle, \"_BCM\") &&\n	    acpi_has_method(handle, \"_BCL\")) {\n		acpi_handle_debug(handle, \"Found generic backlight support\\n\");\n		*cap |= ACPI_VIDEO_BACKLIGHT;\n		/* We have backlight support, no need to scan further */\n		return AE_CTRL_TERMINATE;\n	}\n	return 0;\n}\n\n/* Returns true if the ACPI object is a video device which can be\n * handled by video.ko.\n * The device will get a Linux specific CID added in scan.c to\n * identify the device as an ACPI graphics device\n * Be aware that the graphics device may not be physically present\n */\nlong acpi_is_video_device(acpi_handle handle)\n{\n	long video_caps = 0;\n\n	/* Is this device able to support video switching ? */\n	if (acpi_has_method(handle, \"_DOD\") || acpi_has_method(handle, \"_DOS\"))\n		video_caps |= ACPI_VIDEO_OUTPUT_SWITCHING;\n\n	/* Is this device able to retrieve a video ROM ? */\n	if (acpi_has_method(handle, \"_ROM\"))\n		video_caps |= ACPI_VIDEO_ROM_AVAILABLE;\n\n	/* Is this device able to configure which video head to be POSTed ? */\n	if (acpi_has_method(handle, \"_VPO\") &&\n	    acpi_has_method(handle, \"_GPD\") &&\n	    acpi_has_method(handle, \"_SPD\"))\n		video_caps |= ACPI_VIDEO_DEVICE_POSTING;\n\n	/* Only check for backlight functionality if one of the above hit. */\n	if (video_caps)\n		acpi_walk_namespace(ACPI_TYPE_DEVICE, handle,\n				    ACPI_UINT32_MAX, acpi_backlight_cap_match, NULL,\n				    &video_caps, NULL);\n\n	return video_caps;\n}\nEXPORT_SYMBOL(acpi_is_video_device);\n\nconst char *acpi_device_hid(struct acpi_device *device)\n{\n	struct acpi_hardware_id *hid;\n\n	hid = list_first_entry_or_null(&device->pnp.ids, struct acpi_hardware_id, list);\n	if (!hid)\n		return dummy_hid;\n\n	return hid->id;\n}\nEXPORT_SYMBOL(acpi_device_hid);\n\nstatic void acpi_add_id(struct acpi_device_pnp *pnp, const char *dev_id)\n{\n	struct acpi_hardware_id *id;\n\n	id = kmalloc_obj(*id);\n	if (!id)\n		return;\n\n	id->id = kstrdup_const(dev_id, GFP_KERNEL);\n	if (!id->id) {\n		kfree(id);\n		return;\n	}\n\n	list_add_tail(&id->list, &pnp->ids);\n	pnp->type.hardware_id = 1;\n}\n\n/*\n * Old IBM workstations have a DSDT bug wherein the SMBus object\n * lacks the SMBUS01 HID and the methods do not have the necessary \"_\"\n * prefix.  Work around this.\n */\nstatic bool acpi_ibm_smbus_match(acpi_handle handle)\n{\n	char node_name[ACPI_PATH_SEGMENT_LENGTH];\n	struct acpi_buffer path = { sizeof(node_name), node_name };\n\n	if (!dmi_name_in_vendors(\"IBM\"))\n		return false;\n\n	/* Look for SMBS object */\n	if (ACPI_FAILURE(acpi_get_name(handle, ACPI_SINGLE_NAME, &path)) ||\n	    strcmp(\"SMBS\", path.pointer))\n		return false;\n\n	/* Does it have the necessary (but misnamed) methods? */\n	if (acpi_has_method(handle, \"SBI\") &&\n	    acpi_has_method(handle, \"SBR\") &&\n	    acpi_has_method(handle, \"SBW\"))\n		return true;\n\n	return false;\n}\n\nstatic bool acpi_object_is_system_bus(acpi_handle handle)\n{\n	acpi_handle tmp;\n\n	if (ACPI_SUCCESS(acpi_get_handle(NULL, \"\\\\_SB\", &tmp)) &&\n	    tmp == handle)\n		return true;\n	if (ACPI_SUCCESS(acpi_get_handle(NULL, \"\\\\_TZ\", &tmp)) &&\n	    tmp == handle)\n		return true;\n\n	return false;\n}\n\nstatic void acpi_set_pnp_ids(acpi_handle handle, struct acpi_device_pnp *pnp,\n			     int device_type)\n{\n	struct acpi_device_info *info = NULL;\n	struct acpi_pnp_device_id_list *cid_list;\n	int i;\n\n	switch (device_type) {\n	case ACPI_BUS_TYPE_DEVICE:\n		if (handle == ACPI_ROOT_OBJECT) {\n			acpi_add_id(pnp, ACPI_SYSTEM_HID);\n			break;\n		}\n\n		acpi_get_object_info(handle, &info);\n		if (!info) {\n			pr_err(\"%s: Error reading device info\\n\", __func__);\n			return;\n		}\n\n		if (info->valid & ACPI_VALID_HID) {\n			acpi_add_id(pnp, info->hardware_id.string);\n			pnp->type.platform_id = 1;\n		}\n		if (info->valid & ACPI_VALID_CID) {\n			cid_list = &info->compatible_id_list;\n			for (i = 0; i < cid_list->count; i++)\n				acpi_add_id(pnp, cid_list->ids[i].string);\n		}\n		if (info->valid & ACPI_VALID_ADR) {\n			pnp->bus_address = info->address;\n			pnp->type.bus_address = 1;\n		}\n		if (info->valid & ACPI_VALID_UID)\n			pnp->unique_id = kstrdup(info->unique_id.string,\n							GFP_KERNEL);\n		if (info->valid & ACPI_VALID_CLS)\n			acpi_add_id(pnp, info->class_code.string);\n\n		kfree(info);\n\n		/*\n		 * Some devices don't reliably have _HIDs & _CIDs, so add\n		 * synthetic HIDs to make sure drivers can find them.\n		 */\n		if (acpi_is_video_device(handle)) {\n			acpi_add_id(pnp, ACPI_VIDEO_HID);\n			pnp->type.backlight = 1;\n			break;\n		}\n		if (acpi_bay_match(handle))\n			acpi_add_id(pnp, ACPI_BAY_HID);\n		else if (acpi_dock_match(handle))\n			acpi_add_id(pnp, ACPI_DOCK_HID);\n		else if (acpi_ibm_smbus_match(handle))\n			acpi_add_id(pnp, ACPI_SMBUS_IBM_HID);\n		else if (list_empty(&pnp->ids) &&\n			 acpi_object_is_system_bus(handle)) {\n			/* \\_SB, \\_TZ, LNXSYBUS */\n			acpi_add_id(pnp, ACPI_BUS_HID);\n			strscpy(pnp->device_name, ACPI_BUS_DEVICE_NAME);\n			strscpy(pnp->device_class, ACPI_BUS_CLASS);\n		}\n\n		break;\n	case ACPI_BUS_TYPE_POWER:\n		acpi_add_id(pnp, ACPI_POWER_HID);\n		break;\n	case ACPI_BUS_TYPE_PROCESSOR:\n		acpi_add_id(pnp, ACPI_PROCESSOR_OBJECT_HID);\n		break;\n	case ACPI_BUS_TYPE_THERMAL:\n		acpi_add_id(pnp, ACPI_THERMAL_HID);\n		pnp->type.platform_id = 1;\n		break;\n	case ACPI_BUS_TYPE_POWER_BUTTON:\n		acpi_add_id(pnp, ACPI_BUTTON_HID_POWERF);\n		break;\n	case ACPI_BUS_TYPE_SLEEP_BUTTON:\n		acpi_add_id(pnp, ACPI_BUTTON_HID_SLEEPF);\n		break;\n	case ACPI_BUS_TYPE_ECDT_EC:\n		acpi_add_id(pnp, ACPI_ECDT_HID);\n		break;\n	}\n}\n\nvoid acpi_free_pnp_ids(struct acpi_device_pnp *pnp)\n{\n	struct acpi_hardware_id *id, *tmp;\n\n	list_for_each_entry_safe(id, tmp, &pnp->ids, list) {\n		kfree_const(id->id);\n		kfree(id);\n	}\n	kfree(pnp->unique_id);\n}\n\n/**\n * acpi_dma_supported - Check DMA support for the specified device.\n * @adev: The pointer to acpi device\n *\n * Return false if DMA is not supported. Otherwise, return true\n */\nbool acpi_dma_supported(const struct acpi_device *adev)\n{\n	if (!adev)\n		return false;\n\n	if (adev->flags.cca_seen)\n		return true;\n\n	/*\n	* Per ACPI 6.0 sec 6.2.17, assume devices can do cache-coherent\n	* DMA on \"Intel platforms\".  Presumably that includes all x86 and\n	* ia64, and other arches will set CONFIG_ACPI_CCA_REQUIRED=y.\n	*/\n	if (!IS_ENABLED(CONFIG_ACPI_CCA_REQUIRED))\n		return true;\n\n	return false;\n}\n\n/**\n * acpi_get_dma_attr - Check the supported DMA attr for the specified device.\n * @adev: The pointer to acpi device\n *\n * Return enum dev_dma_attr.\n */\nenum dev_dma_attr acpi_get_dma_attr(struct acpi_device *adev)\n{\n	if (!acpi_dma_supported(adev))\n		return DEV_DMA_NOT_SUPPORTED;\n\n	if (adev->flags.coherent_dma)\n		return DEV_DMA_COHERENT;\n	else\n		return DEV_DMA_NON_COHERENT;\n}\n\n/**\n * acpi_dma_get_range() - Get device DMA parameters.\n *\n * @dev: device to configure\n * @map: pointer to DMA ranges result\n *\n * Evaluate DMA regions and return pointer to DMA regions on\n * parsing success; it does not update the passed in values on failure.\n *\n * Return 0 on success, < 0 on failure.\n */\nint acpi_dma_get_range(struct device *dev, const struct bus_dma_region **map)\n{\n	struct acpi_device *adev;\n	LIST_HEAD(list);\n	struct resource_entry *rentry;\n	int ret;\n	struct device *dma_dev = dev;\n	struct bus_dma_region *r;\n\n	/*\n	 * Walk the device tree chasing an ACPI companion with a _DMA\n	 * object while we go. Stop if we find a device with an ACPI\n	 * companion containing a _DMA method.\n	 */\n	do {\n		adev = ACPI_COMPANION(dma_dev);\n		if (adev && acpi_has_method(adev->handle, METHOD_NAME__DMA))\n			break;\n\n		dma_dev = dma_dev->parent;\n	} while (dma_dev);\n\n	if (!dma_dev)\n		return -ENODEV;\n\n	if (!acpi_has_method(adev->handle, METHOD_NAME__CRS)) {\n		acpi_handle_warn(adev->handle, \"_DMA is valid only if _CRS is present\\n\");\n		return -EINVAL;\n	}\n\n	ret = acpi_dev_get_dma_resources(adev, &list);\n	if (ret > 0) {\n		r = kzalloc_objs(*r, ret + 1);\n		if (!r) {\n			ret = -ENOMEM;\n			goto out;\n		}\n\n		*map = r;\n\n		list_for_each_entry(rentry, &list, node) {\n			if (rentry->res->start >= rentry->res->end) {\n				kfree(*map);\n				*map = NULL;\n				ret = -EINVAL;\n				dev_dbg(dma_dev, \"Invalid DMA regions configuration\\n\");\n				goto out;\n			}\n\n			r->cpu_start = rentry->res->start;\n			r->dma_start = rentry->res->start - rentry->offset;\n			r->size = resource_size(rentry->res);\n			r++;\n		}\n	}\n out:\n	acpi_dev_free_resource_list(&list);\n\n	return ret >= 0 ? 0 : ret;\n}\n\n#ifdef CONFIG_IOMMU_API\nint acpi_iommu_fwspec_init(struct device *dev, u32 id,\n			   struct fwnode_handle *fwnode)\n{\n	int ret;\n\n	ret = iommu_fwspec_init(dev, fwnode);\n	if (ret)\n		return ret;\n\n	return iommu_fwspec_add_ids(dev, &id, 1);\n}\n\nstatic int acpi_iommu_configure_id(struct device *dev, const u32 *id_in)\n{\n	int err;\n\n	/* Serialise to make dev->iommu stable under our potential fwspec */\n	mutex_lock(&iommu_probe_device_lock);\n	/* If we already translated the fwspec there is nothing left to do */\n	if (dev_iommu_fwspec_get(dev)) {\n		mutex_unlock(&iommu_probe_device_lock);\n		return 0;\n	}\n\n	err = iort_iommu_configure_id(dev, id_in);\n	if (err && err != -EPROBE_DEFER)\n		err = rimt_iommu_configure_id(dev, id_in);\n	if (err && err != -EPROBE_DEFER)\n		err = viot_iommu_configure(dev);\n\n	mutex_unlock(&iommu_probe_device_lock);\n\n	return err;\n}\n\n#else /* !CONFIG_IOMMU_API */\n\nint acpi_iommu_fwspec_init(struct device *dev, u32 id,\n			   struct fwnode_handle *fwnode)\n{\n	return -ENODEV;\n}\n\nstatic int acpi_iommu_configure_id(struct device *dev, const u32 *id_in)\n{\n	return -ENODEV;\n}\n\n#endif /* !CONFIG_IOMMU_API */\n\n/**\n * acpi_dma_configure_id - Set-up DMA configuration for the device.\n * @dev: The pointer to the device\n * @attr: device dma attributes\n * @input_id: input device id const value pointer\n */\nint acpi_dma_configure_id(struct device *dev, enum dev_dma_attr attr,\n			  const u32 *input_id)\n{\n	int ret;\n\n	if (attr == DEV_DMA_NOT_SUPPORTED) {\n		set_dma_ops(dev, &dma_dummy_ops);\n		return 0;\n	}\n\n	acpi_arch_dma_setup(dev);\n\n	/* Ignore all other errors apart from EPROBE_DEFER */\n	ret = acpi_iommu_configure_id(dev, input_id);\n	if (ret == -EPROBE_DEFER)\n		return -EPROBE_DEFER;\n	if (ret)\n		dev_dbg(dev, \"Adding to IOMMU failed: %d\\n\", ret);\n\n	arch_setup_dma_ops(dev, attr == DEV_DMA_COHERENT);\n\n	return 0;\n}\nEXPORT_SYMBOL_GPL(acpi_dma_configure_id);\n\nstatic void acpi_init_coherency(struct acpi_device *adev)\n{\n	unsigned long long cca = 0;\n	acpi_status status;\n	struct acpi_device *parent = acpi_dev_parent(adev);\n\n	if (parent && parent->flags.cca_seen) {\n		/*\n		 * From ACPI spec, OSPM will ignore _CCA if an ancestor\n		 * already saw one.\n		 */\n		adev->flags.cca_seen = 1;\n		cca = parent->flags.coherent_dma;\n	} else {\n		status = acpi_evaluate_integer(adev->handle, \"_CCA\",\n					       NULL, &cca);\n		if (ACPI_SUCCESS(status))\n			adev->flags.cca_seen = 1;\n		else if (!IS_ENABLED(CONFIG_ACPI_CCA_REQUIRED))\n			/*\n			 * If architecture does not specify that _CCA is\n			 * required for DMA-able devices (e.g. x86),\n			 * we default to _CCA=1.\n			 */\n			cca = 1;\n		else\n			acpi_handle_debug(adev->handle,\n					  \"ACPI device is missing _CCA.\\n\");\n	}\n\n	adev->flags.coherent_dma = cca;\n}\n\nstatic int acpi_check_serial_bus_slave(struct acpi_resource *ares, void *data)\n{\n	bool *is_serial_bus_slave_p = data;\n\n	if (ares->type != ACPI_RESOURCE_TYPE_SERIAL_BUS)\n		return 1;\n\n	*is_serial_bus_slave_p = true;\n\n	 /* no need to do more checking */\n	return -1;\n}\n\nstatic bool acpi_is_indirect_io_slave(struct acpi_device *device)\n{\n	struct acpi_device *parent = acpi_dev_parent(device);\n	static const struct acpi_device_id indirect_io_hosts[] = {\n		{\"HISI0191\", 0},\n		{}\n	};\n\n	return parent && !acpi_match_device_ids(parent, indirect_io_hosts);\n}\n\nstatic bool acpi_device_enumeration_by_parent(struct acpi_device *device)\n{\n	struct list_head resource_list;\n	bool is_serial_bus_slave = false;\n	static const struct acpi_device_id ignore_serial_bus_ids[] = {\n	/*\n	 * These devices have multiple SerialBus resources and a client\n	 * device must be instantiated for each of them, each with\n	 * its own device id.\n	 * Normally we only instantiate one client device for the first\n	 * resource, using the ACPI HID as id. These special cases are handled\n	 * by the drivers/platform/x86/serial-multi-instantiate.c driver, which\n	 * knows which client device id to use for each resource.\n	 */\n		{\"AWDZ8399\", },\n		{\"BSG1160\", },\n		{\"BSG2150\", },\n		{\"CSC3551\", },\n		{\"CSC3554\", },\n		{\"CSC3556\", },\n		{\"CSC3557\", },\n		{\"INT33FE\", },\n		{\"INT3515\", },\n		{\"TXNW2781\", },\n		/* Non-conforming _HID for Cirrus Logic already released */\n		{\"CLSA0100\", },\n		{\"CLSA0101\", },\n	/*\n	 * Some ACPI devs contain SerialBus resources even though they are not\n	 * attached to a serial bus at all.\n	 */\n		{\"MSHW0028\", },\n	/*\n	 * HIDs of device with an UartSerialBusV2 resource for which userspace\n	 * expects a regular tty cdev to be created (instead of the in kernel\n	 * serdev) and which have a kernel driver which expects a platform_dev\n	 * such as the rfkill-gpio driver.\n	 */\n		{\"BCM4752\", },\n		{\"LNV4752\", },\n		{}\n	};\n\n	if (acpi_is_indirect_io_slave(device))\n		return true;\n\n	/* Macs use device properties in lieu of _CRS resources */\n	if (x86_apple_machine &&\n	    (fwnode_property_present(&device->fwnode, \"spiSclkPeriod\") ||\n	     fwnode_property_present(&device->fwnode, \"i2cAddress\") ||\n	     fwnode_property_present(&device->fwnode, \"baud\")))\n		return true;\n\n	if (acpi_dev_is_video_device(device))\n		return false;\n\n	if (!acpi_match_device_ids(device, ignore_serial_bus_ids))\n		return false;\n\n	INIT_LIST_HEAD(&resource_list);\n	acpi_dev_get_resources(device, &resource_list,\n			       acpi_check_serial_bus_slave,\n			       &is_serial_bus_slave);\n	acpi_dev_free_resource_list(&resource_list);\n\n	return is_serial_bus_slave;\n}\n\nvoid acpi_init_device_object(struct acpi_device *device, acpi_handle handle,\n			     int type, void (*release)(struct device *))\n{\n	struct acpi_device *parent = acpi_find_parent_acpi_dev(handle);\n\n	INIT_LIST_HEAD(&device->pnp.ids);\n	device->device_type = type;\n	device->handle = handle;\n	device->dev.parent = parent ? &parent->dev : NULL;\n	device->dev.release = release;\n	device->dev.bus = &acpi_bus_type;\n	device->dev.groups = acpi_groups;\n	device_set_pm_not_required(&device->dev);\n	fwnode_init(&device->fwnode, &acpi_device_fwnode_ops);\n	acpi_set_device_status(device, ACPI_STA_DEFAULT);\n	acpi_device_get_busid(device);\n	acpi_set_pnp_ids(handle, &device->pnp, type);\n	acpi_init_properties(device);\n	acpi_bus_get_flags(device);\n	device->flags.initialized = true;\n	device->flags.enumeration_by_parent =\n		acpi_device_enumeration_by_parent(device);\n	acpi_device_clear_enumerated(device);\n	device_initialize(&device->dev);\n	dev_set_uevent_suppress(&device->dev, true);\n	acpi_init_coherency(device);\n}\n\nstatic void acpi_scan_dep_init(struct acpi_device *adev)\n{\n	struct acpi_dep_data *dep;\n\n	list_for_each_entry(dep, &acpi_dep_list, node) {\n		if (dep->consumer == adev->handle) {\n			if (dep->honor_dep)\n				adev->flags.honor_deps = 1;\n\n			if (!dep->met)\n				adev->dep_unmet++;\n		}\n	}\n}\n\nvoid acpi_device_add_finalize(struct acpi_device *device)\n{\n	dev_set_uevent_suppress(&device->dev, false);\n	kobject_uevent(&device->dev.kobj, KOBJ_ADD);\n}\n\nstatic void acpi_scan_init_status(struct acpi_device *adev)\n{\n	if (acpi_bus_get_status(adev))\n		acpi_set_device_status(adev, 0);\n}\n\nstatic int acpi_add_single_object(struct acpi_device **child,\n				  acpi_handle handle, int type, bool dep_init)\n{\n	struct acpi_device *device;\n	bool release_dep_lock = false;\n	int result;\n\n	device = kzalloc_obj(struct acpi_device);\n	if (!device)\n		return -ENOMEM;\n\n	acpi_init_device_object(device, handle, type, acpi_device_release);\n	/*\n	 * Getting the status is delayed till here so that we can call\n	 * acpi_bus_get_status() and use its quirk handling.  Note that\n	 * this must be done before the get power-/wakeup_dev-flags calls.\n	 */\n	if (type == ACPI_BUS_TYPE_DEVICE || type == ACPI_BUS_TYPE_PROCESSOR) {\n		if (dep_init) {\n			mutex_lock(&acpi_dep_list_lock);\n			/*\n			 * Hold the lock until the acpi_tie_acpi_dev() call\n			 * below to prevent concurrent acpi_scan_clear_dep()\n			 * from deleting a dependency list entry without\n			 * updating dep_unmet for the device.\n			 */\n			release_dep_lock = true;\n			acpi_scan_dep_init(device);\n		}\n		acpi_scan_init_status(device);\n	}\n\n	acpi_bus_get_power_flags(device);\n	acpi_bus_get_wakeup_device_flags(device);\n\n	result = acpi_tie_acpi_dev(device);\n\n	if (release_dep_lock)\n		mutex_unlock(&acpi_dep_list_lock);\n\n	if (!result)\n		result = acpi_device_add(device);\n\n	if (result) {\n		acpi_dev_put(device);\n		return result;\n	}\n\n	acpi_power_add_remove_device(device, true);\n	acpi_device_add_finalize(device);\n\n	acpi_handle_debug(handle, \"Added as %s, parent %s\\n\",\n			  dev_name(&device->dev), device->dev.parent ?\n				dev_name(device->dev.parent) : \"(null)\");\n\n	*child = device;\n	return 0;\n}\n\nstatic acpi_status acpi_get_resource_memory(struct acpi_resource *ares,\n					    void *context)\n{\n	struct resource *res = context;\n\n	if (acpi_dev_resource_memory(ares, res))\n		return AE_CTRL_TERMINATE;\n\n	return AE_OK;\n}\n\nstatic bool acpi_device_should_be_hidden(acpi_handle handle)\n{\n	acpi_status status;\n	struct resource res;\n\n	/* Check if it should ignore the UART device */\n	if (!(spcr_uart_addr && acpi_has_method(handle, METHOD_NAME__CRS)))\n		return false;\n\n	/*\n	 * The UART device described in SPCR table is assumed to have only one\n	 * memory resource present. So we only look for the first one here.\n	 */\n	status = acpi_walk_resources(handle, METHOD_NAME__CRS,\n				     acpi_get_resource_memory, &res);\n	if (ACPI_FAILURE(status) || res.start != spcr_uart_addr)\n		return false;\n\n	acpi_handle_info(handle, \"The UART device @%pa in SPCR table will be hidden\\n\",\n			 &res.start);\n\n	return true;\n}\n\nbool acpi_device_is_present(const struct acpi_device *adev)\n{\n	return adev->status.present || adev->status.functional;\n}\n\nbool acpi_device_is_enabled(const struct acpi_device *adev)\n{\n	return adev->status.enabled;\n}\n\nstatic bool acpi_scan_handler_matching(struct acpi_scan_handler *handler,\n				       const char *idstr,\n				       const struct acpi_device_id **matchid)\n{\n	const struct acpi_device_id *devid;\n\n	if (handler->match)\n		return handler->match(idstr, matchid);\n\n	for (devid = handler->ids; devid->id[0]; devid++)\n		if (!strcmp((char *)devid->id, idstr)) {\n			if (matchid)\n				*matchid = devid;\n\n			return true;\n		}\n\n	return false;\n}\n\nstatic struct acpi_scan_handler *acpi_scan_match_handler(const char *idstr,\n					const struct acpi_device_id **matchid)\n{\n	struct acpi_scan_handler *handler;\n\n	list_for_each_entry(handler, &acpi_scan_handlers_list, list_node)\n		if (acpi_scan_handler_matching(handler, idstr, matchid))\n			return handler;\n\n	return NULL;\n}\n\nvoid acpi_scan_hotplug_enabled(struct acpi_hotplug_profile *hotplug, bool val)\n{\n	if (!!hotplug->enabled == !!val)\n		return;\n\n	mutex_lock(&acpi_scan_lock);\n\n	hotplug->enabled = val;\n\n	mutex_unlock(&acpi_scan_lock);\n}\n\nint acpi_scan_add_dep(acpi_handle handle, struct acpi_handle_list *dep_devices)\n{\n	u32 count;\n	int i;\n\n	for (count = 0, i = 0; i < dep_devices->count; i++) {\n		struct acpi_device_info *info;\n		struct acpi_dep_data *dep;\n		bool skip, honor_dep;\n		acpi_status status;\n\n		status = acpi_get_object_info(dep_devices->handles[i], &info);\n		if (ACPI_FAILURE(status)) {\n			acpi_handle_debug(handle, \"Error reading _DEP device info\\n\");\n			continue;\n		}\n\n		skip = acpi_info_matches_ids(info, acpi_ignore_dep_ids);\n		honor_dep = acpi_info_matches_ids(info, acpi_honor_dep_ids);\n		kfree(info);\n\n		if (skip)\n			continue;\n\n		dep = kzalloc_obj(*dep);\n		if (!dep)\n			continue;\n\n		count++;\n\n		dep->supplier = dep_devices->handles[i];\n		dep->consumer = handle;\n		dep->honor_dep = honor_dep;\n\n		mutex_lock(&acpi_dep_list_lock);\n		list_add_tail(&dep->node, &acpi_dep_list);\n		mutex_unlock(&acpi_dep_list_lock);\n	}\n\n	acpi_handle_list_free(dep_devices);\n	return count;\n}\n\nstatic void acpi_scan_init_hotplug(struct acpi_device *adev)\n{\n	struct acpi_hardware_id *hwid;\n\n	if (acpi_dock_match(adev->handle) || is_ejectable_bay(adev)) {\n		acpi_dock_add(adev);\n		return;\n	}\n	list_for_each_entry(hwid, &adev->pnp.ids, list) {\n		struct acpi_scan_handler *handler;\n\n		handler = acpi_scan_match_handler(hwid->id, NULL);\n		if (handler) {\n			adev->flags.hotplug_notify = true;\n			break;\n		}\n	}\n}\n\nu32 __weak arch_acpi_add_auto_dep(acpi_handle handle) { return 0; }\n\nstatic u32 acpi_scan_check_dep(acpi_handle handle)\n{\n	struct acpi_handle_list dep_devices;\n	u32 count = 0;\n\n	/*\n	 * Some architectures like RISC-V need to add dependencies for\n	 * all devices which use GSI to the interrupt controller so that\n	 * interrupt controller is probed before any of those devices.\n	 * Instead of mandating _DEP on all the devices, detect the\n	 * dependency and add automatically.\n	 */\n	count += arch_acpi_add_auto_dep(handle);\n\n	/*\n	 * Check for _HID here to avoid deferring the enumeration of:\n	 * 1. PCI devices.\n	 * 2. ACPI nodes describing USB ports.\n	 * Still, checking for _HID catches more then just these cases ...\n	 */\n	if (!acpi_has_method(handle, \"_DEP\") || !acpi_has_method(handle, \"_HID\"))\n		return count;\n\n	if (!acpi_evaluate_reference(handle, \"_DEP\", NULL, &dep_devices)) {\n		acpi_handle_debug(handle, \"Failed to evaluate _DEP.\\n\");\n		return count;\n	}\n\n	count += acpi_scan_add_dep(handle, &dep_devices);\n	return count;\n}\n\nstatic acpi_status acpi_scan_check_crs_csi2_cb(acpi_handle handle, u32 a, void *b, void **c)\n{\n	acpi_mipi_check_crs_csi2(handle);\n	return AE_OK;\n}\n\nstatic acpi_status acpi_bus_check_add(acpi_handle handle, bool first_pass,\n				      struct acpi_device **adev_p)\n{\n	struct acpi_device *device = acpi_fetch_acpi_dev(handle);\n	acpi_object_type acpi_type;\n	int type;\n\n	if (device)\n		goto out;\n\n	if (ACPI_FAILURE(acpi_get_type(handle, &acpi_type)))\n		return AE_OK;\n\n	switch (acpi_type) {\n	case ACPI_TYPE_DEVICE:\n		if (acpi_device_should_be_hidden(handle))\n			return AE_OK;\n\n		if (first_pass) {\n			acpi_mipi_check_crs_csi2(handle);\n\n			/* Bail out if there are dependencies. */\n			if (acpi_scan_check_dep(handle) > 0) {\n				/*\n				 * The entire CSI-2 connection graph needs to be\n				 * extracted before any drivers or scan handlers\n				 * are bound to struct device objects, so scan\n				 * _CRS CSI-2 resource descriptors for all\n				 * devices below the current handle.\n				 */\n				acpi_walk_namespace(ACPI_TYPE_DEVICE, handle,\n						    ACPI_UINT32_MAX,\n						    acpi_scan_check_crs_csi2_cb,\n						    NULL, NULL, NULL);\n				return AE_CTRL_DEPTH;\n			}\n		}\n\n		fallthrough;\n	case ACPI_TYPE_ANY:	/* for ACPI_ROOT_OBJECT */\n		type = ACPI_BUS_TYPE_DEVICE;\n		break;\n\n	case ACPI_TYPE_PROCESSOR:\n		type = ACPI_BUS_TYPE_PROCESSOR;\n		break;\n\n	case ACPI_TYPE_THERMAL:\n		type = ACPI_BUS_TYPE_THERMAL;\n		break;\n\n	case ACPI_TYPE_POWER:\n		acpi_add_power_resource(handle);\n		fallthrough;\n	default:\n		return AE_OK;\n	}\n\n	/*\n	 * If first_pass is true at this point, the device has no dependencies,\n	 * or the creation of the device object would have been postponed above.\n	 */\n	acpi_add_single_object(&device, handle, type, !first_pass);\n	if (!device)\n		return AE_CTRL_DEPTH;\n\n	acpi_scan_init_hotplug(device);\n\nout:\n	if (!*adev_p)\n		*adev_p = device;\n\n	return AE_OK;\n}\n\nstatic acpi_status acpi_bus_check_add_1(acpi_handle handle, u32 lvl_not_used,\n					void *not_used, void **ret_p)\n{\n	return acpi_bus_check_add(handle, true, (struct acpi_device **)ret_p);\n}\n\nstatic acpi_status acpi_bus_check_add_2(acpi_handle handle, u32 lvl_not_used,\n					void *not_used, void **ret_p)\n{\n	return acpi_bus_check_add(handle, false, (struct acpi_device **)ret_p);\n}\n\nstatic void acpi_video_bus_device_release(struct device *dev)\n{\n	struct auxiliary_device *aux_dev = to_auxiliary_dev(dev);\n\n	kfree(aux_dev);\n}\n\nstatic void acpi_create_video_bus_device(struct acpi_device *adev,\n					 struct acpi_device *parent)\n{\n	struct auxiliary_device *aux_dev;\n	static unsigned int aux_dev_id;\n\n	struct device *phys_parent __free(put_device) = acpi_bus_get_primary_device(parent);\n	if (!phys_parent)\n		return;\n\n	aux_dev = kzalloc_obj(*aux_dev);\n	if (!aux_dev)\n		return;\n\n	aux_dev->id = aux_dev_id++;\n	aux_dev->name = \"video_bus\";\n	aux_dev->dev.parent = phys_parent;\n	aux_dev->dev.release = acpi_video_bus_device_release;\n\n	if (auxiliary_device_init(aux_dev)) {\n		kfree(aux_dev);\n		return;\n	}\n\n	ACPI_COMPANION_SET(&aux_dev->dev, adev);\n	if (__auxiliary_device_add(aux_dev, \"acpi\"))\n		auxiliary_device_uninit(aux_dev);\n}\n\nstruct acpi_scan_system_dev {\n	struct list_head node;\n	struct acpi_device *adev;\n};\n\nstatic const char * const acpi_system_dev_ids[] = {\n	\"PNP0C01\", /* Memory controller */\n	\"PNP0C02\", /* Motherboard resource */\n	NULL\n};\n\nstatic void acpi_default_enumeration(struct acpi_device *device)\n{\n	/*\n	 * Do not enumerate devices with enumeration_by_parent flag set as\n	 * they will be enumerated by their respective parents.\n	 */\n	if (device->flags.enumeration_by_parent) {\n		blocking_notifier_call_chain(&acpi_reconfig_chain,\n					     ACPI_RECONFIG_DEVICE_ADD, device);\n		return;\n	}\n	if (match_string(acpi_system_dev_ids, -1, acpi_device_hid(device)) >= 0) {\n		struct acpi_scan_system_dev *sd;\n\n		/*\n		 * This is a generic system device, so there is no need to\n		 * create a platform device for it, but its resources need to be\n		 * reserved.  However, that needs to be done after all of the\n		 * other device objects have been processed and PCI has claimed\n		 * BARs in case there are resource conflicts.\n		 */\n		sd = kmalloc_obj(*sd);\n		if (sd) {\n			sd->adev = device;\n			list_add_tail(&sd->node, &acpi_scan_system_dev_list);\n		}\n	} else if (device->pnp.type.backlight) {\n		struct acpi_device *parent;\n\n		parent = acpi_dev_parent(device);\n		if (parent)\n			acpi_create_video_bus_device(device, parent);\n	} else {\n		/* For a regular device object, create a platform device. */\n		acpi_create_platform_device(device, NULL);\n	}\n	acpi_device_set_enumerated(device);\n}\n\nstatic const struct acpi_device_id generic_device_ids[] = {\n	{ACPI_DT_NAMESPACE_HID, },\n	{\"\", },\n};\n\nstatic int acpi_generic_device_attach(struct acpi_device *adev,\n				      const struct acpi_device_id *not_used)\n{\n	/*\n	 * Since ACPI_DT_NAMESPACE_HID is the only ID handled here, the test\n	 * below can be unconditional.\n	 */\n	if (adev->data.of_compatible)\n		acpi_default_enumeration(adev);\n\n	return 1;\n}\n\nstatic struct acpi_scan_handler generic_device_handler = {\n	.ids = generic_device_ids,\n	.attach = acpi_generic_device_attach,\n};\n\nstatic int acpi_scan_attach_handler(struct acpi_device *device)\n{\n	struct acpi_hardware_id *hwid;\n	int ret = 0;\n\n	list_for_each_entry(hwid, &device->pnp.ids, list) {\n		const struct acpi_device_id *devid;\n		struct acpi_scan_handler *handler;\n\n		handler = acpi_scan_match_handler(hwid->id, &devid);\n		if (handler) {\n			if (!handler->attach) {\n				device->pnp.type.platform_id = 0;\n				continue;\n			}\n			device->handler = handler;\n			ret = handler->attach(device, devid);\n			if (ret > 0)\n				break;\n\n			device->handler = NULL;\n			if (ret < 0)\n				break;\n		}\n	}\n\n	return ret;\n}\n\nstatic int acpi_bus_attach(struct acpi_device *device, void *first_pass)\n{\n	bool skip = !first_pass && device->flags.visited;\n	acpi_handle ejd;\n	int ret;\n\n	if (skip)\n		goto ok;\n\n	if (ACPI_SUCCESS(acpi_bus_get_ejd(device->handle, &ejd)))\n		register_dock_dependent_device(device, ejd);\n\n	acpi_bus_get_status(device);\n	/* Skip devices that are not ready for enumeration (e.g. not present) */\n	if (!acpi_dev_ready_for_enumeration(device)) {\n		device->flags.initialized = false;\n		acpi_device_clear_enumerated(device);\n		device->flags.power_manageable = 0;\n		return 0;\n	}\n	if (device->handler)\n		goto ok;\n\n	acpi_ec_register_opregions(device);\n\n	if (!device->flags.initialized) {\n		device->flags.power_manageable =\n			device->power.states[ACPI_STATE_D0].flags.valid;\n		if (acpi_bus_init_power(device))\n			device->flags.power_manageable = 0;\n\n		device->flags.initialized = true;\n	} else if (device->flags.visited) {\n		goto ok;\n	}\n\n	ret = acpi_scan_attach_handler(device);\n	if (ret < 0)\n		return 0;\n\n	if (ret > 0 && !device->flags.enumeration_by_parent) {\n		acpi_device_set_enumerated(device);\n		goto ok;\n	}\n\n	if (device->pnp.type.platform_id || device->pnp.type.backlight ||\n	    device->flags.enumeration_by_parent)\n		acpi_default_enumeration(device);\n	else\n		acpi_device_set_enumerated(device);\n\nok:\n	acpi_dev_for_each_child(device, acpi_bus_attach, first_pass);\n\n	if (!skip && device->handler && device->handler->hotplug.notify_online)\n		device->handler->hotplug.notify_online(device);\n\n	return 0;\n}\n\nstatic int acpi_dev_get_next_consumer_dev_cb(struct acpi_dep_data *dep, void *data)\n{\n	struct acpi_device **adev_p = data;\n	struct acpi_device *adev = *adev_p;\n\n	/*\n	 * If we're passed a 'previous' consumer device then we need to skip\n	 * any consumers until we meet the previous one, and then NULL @data\n	 * so the next one can be returned.\n	 */\n	if (adev) {\n		if (dep->consumer == adev->handle)\n			*adev_p = NULL;\n\n		return 0;\n	}\n\n	adev = acpi_get_acpi_dev(dep->consumer);\n	if (adev) {\n		*(struct acpi_device **)data = adev;\n		return 1;\n	}\n	/* Continue parsing if the device object is not present. */\n	return 0;\n}\n\nstatic void acpi_scan_clear_dep_fn(void *dev, async_cookie_t cookie)\n{\n	struct acpi_device *adev = to_acpi_device(dev);\n\n	acpi_scan_lock_acquire();\n	acpi_bus_attach(adev, (void *)true);\n	acpi_scan_lock_release();\n\n	acpi_dev_put(adev);\n}\n\nstatic bool acpi_scan_clear_dep_queue(struct acpi_device *adev)\n{\n	if (adev->dep_unmet)\n		return false;\n\n	/*\n	 * Async schedule the deferred acpi_scan_clear_dep_fn() since:\n	 * - acpi_bus_attach() needs to hold acpi_scan_lock which cannot\n	 *   be acquired under acpi_dep_list_lock (held here)\n	 * - the deferred work at boot stage is ensured to be finished\n	 *   before userspace init task by the async_synchronize_full()\n	 *   barrier\n	 *\n	 * Use _nocall variant since it'll return on failure instead of\n	 * run the function synchronously.\n	 */\n	return async_schedule_dev_nocall(acpi_scan_clear_dep_fn, &adev->dev);\n}\n\nstatic void acpi_scan_delete_dep_data(struct acpi_dep_data *dep)\n{\n	list_del(&dep->node);\n	kfree(dep);\n}\n\nstatic int acpi_scan_clear_dep(struct acpi_dep_data *dep, void *data)\n{\n	struct acpi_device *adev = acpi_get_acpi_dev(dep->consumer);\n\n	if (adev) {\n		adev->dep_unmet--;\n		if (!acpi_scan_clear_dep_queue(adev))\n			acpi_dev_put(adev);\n	}\n\n	if (dep->free_when_met)\n		acpi_scan_delete_dep_data(dep);\n	else\n		dep->met = true;\n\n	return 0;\n}\n\n/**\n * acpi_walk_dep_device_list - Apply a callback to every entry in acpi_dep_list\n * @handle:	The ACPI handle of the supplier device\n * @callback:	Pointer to the callback function to apply\n * @data:	Pointer to some data to pass to the callback\n *\n * The return value of the callback determines this function's behaviour. If 0\n * is returned we continue to iterate over acpi_dep_list. If a positive value\n * is returned then the loop is broken but this function returns 0. If a\n * negative value is returned by the callback then the loop is broken and that\n * value is returned as the final error.\n */\nstatic int acpi_walk_dep_device_list(acpi_handle handle,\n				int (*callback)(struct acpi_dep_data *, void *),\n				void *data)\n{\n	struct acpi_dep_data *dep, *tmp;\n	int ret = 0;\n\n	mutex_lock(&acpi_dep_list_lock);\n	list_for_each_entry_safe(dep, tmp, &acpi_dep_list, node) {\n		if (dep->supplier == handle) {\n			ret = callback(dep, data);\n			if (ret)\n				break;\n		}\n	}\n	mutex_unlock(&acpi_dep_list_lock);\n\n	return ret > 0 ? 0 : ret;\n}\n\n/**\n * acpi_dev_clear_dependencies - Inform consumers that the device is now active\n * @supplier: Pointer to the supplier &struct acpi_device\n *\n * Clear dependencies on the given device.\n */\nvoid acpi_dev_clear_dependencies(struct acpi_device *supplier)\n{\n	acpi_walk_dep_device_list(supplier->handle, acpi_scan_clear_dep, NULL);\n}\nEXPORT_SYMBOL_GPL(acpi_dev_clear_dependencies);\n\n/**\n * acpi_dev_ready_for_enumeration - Check if the ACPI device is ready for enumeration\n * @device: Pointer to the &struct acpi_device to check\n *\n * Check if the device is present and has no unmet dependencies.\n *\n * Return true if the device is ready for enumeratino. Otherwise, return false.\n */\nbool acpi_dev_ready_for_enumeration(const struct acpi_device *device)\n{\n	if (device->flags.honor_deps && device->dep_unmet)\n		return false;\n\n	return acpi_device_is_present(device);\n}\nEXPORT_SYMBOL_GPL(acpi_dev_ready_for_enumeration);\n\n/**\n * acpi_dev_get_next_consumer_dev - Return the next adev dependent on @supplier\n * @supplier: Pointer to the dependee device\n * @start: Pointer to the current dependent device\n *\n * Returns the next &struct acpi_device which declares itself dependent on\n * @supplier via the _DEP buffer, parsed from the acpi_dep_list.\n *\n * If the returned adev is not passed as @start to this function, the caller is\n * responsible for putting the reference to adev when it is no longer needed.\n */\nstruct acpi_device *acpi_dev_get_next_consumer_dev(struct acpi_device *supplier,\n						   struct acpi_device *start)\n{\n	struct acpi_device *adev = start;\n\n	acpi_walk_dep_device_list(supplier->handle,\n				  acpi_dev_get_next_consumer_dev_cb, &adev);\n\n	acpi_dev_put(start);\n\n	if (adev == start)\n		return NULL;\n\n	return adev;\n}\nEXPORT_SYMBOL_GPL(acpi_dev_get_next_consumer_dev);\n\nstatic void acpi_scan_postponed_branch(acpi_handle handle)\n{\n	struct acpi_device *adev = NULL;\n\n	if (ACPI_FAILURE(acpi_bus_check_add(handle, false, &adev)))\n		return;\n\n	acpi_walk_namespace(ACPI_TYPE_ANY, handle, ACPI_UINT32_MAX,\n			    acpi_bus_check_add_2, NULL, NULL, (void **)&adev);\n\n	/*\n	 * Populate the ACPI _CRS CSI-2 software nodes for the ACPI devices that\n	 * have been added above.\n	 */\n	acpi_mipi_init_crs_csi2_swnodes();\n\n	acpi_bus_attach(adev, NULL);\n}\n\nstatic void acpi_scan_postponed(void)\n{\n	struct acpi_dep_data *dep, *tmp;\n\n	mutex_lock(&acpi_dep_list_lock);\n\n	list_for_each_entry_safe(dep, tmp, &acpi_dep_list, node) {\n		acpi_handle handle = dep->consumer;\n\n		/*\n		 * In case there are multiple acpi_dep_list entries with the\n		 * same consumer, skip the current entry if the consumer device\n		 * object corresponding to it is present already.\n		 */\n		if (!acpi_fetch_acpi_dev(handle)) {\n			/*\n			 * Even though the lock is released here, tmp is\n			 * guaranteed to be valid, because none of the list\n			 * entries following dep is marked as \"free when met\"\n			 * and so they cannot be deleted.\n			 */\n			mutex_unlock(&acpi_dep_list_lock);\n\n			acpi_scan_postponed_branch(handle);\n\n			mutex_lock(&acpi_dep_list_lock);\n		}\n\n		if (dep->met)\n			acpi_scan_delete_dep_data(dep);\n		else\n			dep->free_when_met = true;\n	}\n\n	mutex_unlock(&acpi_dep_list_lock);\n}\n\nstatic void acpi_scan_claim_resources(struct acpi_device *adev)\n{\n	struct resource_entry *rentry;\n	LIST_HEAD(resource_list);\n	unsigned int count = 0;\n	const char *regionid;\n\n	if (acpi_dev_get_resources(adev, &resource_list, NULL, NULL) <= 0)\n		return;\n\n	regionid = kstrdup(dev_name(&adev->dev), GFP_KERNEL);\n	if (!regionid)\n		goto exit;\n\n	list_for_each_entry(rentry, &resource_list, node) {\n		struct resource *res = rentry->res;\n		struct resource *r;\n\n		/* Skip disabled and invalid resources. */\n		if ((res->flags & IORESOURCE_DISABLED) || res->end < res->start)\n			continue;\n\n		if (resource_type(res) == IORESOURCE_IO) {\n			/*\n			 * Follow the PNP system driver and on x86 skip I/O\n			 * resources that start below 0x100 (the \"standard PC\n			 * hardware\" boundary).\n			 */\n			if (IS_ENABLED(CONFIG_X86) && res->start < 0x100) {\n				dev_info(&adev->dev, \"Skipped %pR\\n\", res);\n				continue;\n			}\n			r = request_region(res->start, resource_size(res), regionid);\n		} else if (resource_type(res) == IORESOURCE_MEM) {\n			r = request_mem_region(res->start, resource_size(res), regionid);\n		} else {\n			continue;\n		}\n\n		if (r) {\n			r->flags &= ~IORESOURCE_BUSY;\n			dev_info(&adev->dev, \"Reserved %pR\\n\", r);\n			count++;\n		} else {\n			/*\n			 * Failures at this point are usually harmless. PCI\n			 * quirks, for example, reserve resources they know\n			 * about too, so there may well be double reservations.\n			 */\n			dev_info(&adev->dev, \"Could not reserve %pR\\n\", res);\n		}\n	}\n\n	if (!count)\n		kfree(regionid);\n\nexit:\n	acpi_dev_free_resource_list(&resource_list);\n}\n\nstatic int __init acpi_reserve_motherboard_resources(void)\n{\n	struct acpi_scan_system_dev *sd, *tmp;\n\n	guard(mutex)(&acpi_scan_lock);\n\n	list_for_each_entry_safe(sd, tmp, &acpi_scan_system_dev_list, node) {\n		acpi_scan_claim_resources(sd->adev);\n		list_del(&sd->node);\n		kfree(sd);\n	}\n\n	return 0;\n}\n\n/*\n * Reserve motherboard resources after PCI claims BARs, but before PCI assigns\n * resources for uninitialized PCI devices.\n */\nfs_initcall(acpi_reserve_motherboard_resources);\n\n/**\n * acpi_bus_scan - Add ACPI device node objects in a given namespace scope.\n * @handle: Root of the namespace scope to scan.\n *\n * Scan a given ACPI tree (probably recently hot-plugged) and create and add\n * found devices.\n *\n * If no devices were found, -ENODEV is returned, but it does not mean that\n * there has been a real error.  There just have been no suitable ACPI objects\n * in the table trunk from which the kernel could create a device and add an\n * appropriate driver.\n *\n * Must be called under acpi_scan_lock.\n */\nint acpi_bus_scan(acpi_handle handle)\n{\n	struct acpi_device *device = NULL;\n\n	/* Pass 1: Avoid enumerating devices with missing dependencies. */\n\n	if (ACPI_SUCCESS(acpi_bus_check_add(handle, true, &device)))\n		acpi_walk_namespace(ACPI_TYPE_ANY, handle, ACPI_UINT32_MAX,\n				    acpi_bus_check_add_1, NULL, NULL,\n				    (void **)&device);\n\n	if (!device)\n		return -ENODEV;\n\n	/*\n	 * Set up ACPI _CRS CSI-2 software nodes using information extracted\n	 * from the _CRS CSI-2 resource descriptors during the ACPI namespace\n	 * walk above and MIPI DisCo for Imaging device properties.\n	 */\n	acpi_mipi_scan_crs_csi2();\n	acpi_mipi_init_crs_csi2_swnodes();\n\n	acpi_bus_attach(device, (void *)true);\n\n	/* Pass 2: Enumerate all of the remaining devices. */\n\n	acpi_scan_postponed();\n\n	acpi_mipi_crs_csi2_cleanup();\n\n	return 0;\n}\nEXPORT_SYMBOL(acpi_bus_scan);\n\n/**\n * acpi_bus_trim - Detach scan handlers and drivers from ACPI device objects.\n * @adev: Root of the ACPI namespace scope to walk.\n *\n * Must be called under acpi_scan_lock.\n */\nvoid acpi_bus_trim(struct acpi_device *adev)\n{\n	uintptr_t flags = 0;\n\n	acpi_scan_check_and_detach(adev, (void *)flags);\n}\nEXPORT_SYMBOL_GPL(acpi_bus_trim);\n\nint acpi_bus_register_early_device(int type)\n{\n	struct acpi_device *device = NULL;\n	int result;\n\n	result = acpi_add_single_object(&device, NULL, type, false);\n	if (result)\n		return result;\n\n	acpi_default_enumeration(device);\n	return 0;\n}\nEXPORT_SYMBOL_GPL(acpi_bus_register_early_device);\n\nstatic void acpi_bus_add_fixed_device_object(enum acpi_bus_device_type type)\n{\n	struct acpi_device *adev = NULL;\n\n	acpi_add_single_object(&adev, NULL, type, false);\n	if (adev)\n		acpi_default_enumeration(adev);\n}\n\nstatic void acpi_bus_scan_fixed(void)\n{\n	if (!(acpi_gbl_FADT.flags & ACPI_FADT_POWER_BUTTON))\n		acpi_bus_add_fixed_device_object(ACPI_BUS_TYPE_POWER_BUTTON);\n\n	if (!(acpi_gbl_FADT.flags & ACPI_FADT_SLEEP_BUTTON))\n		acpi_bus_add_fixed_device_object(ACPI_BUS_TYPE_SLEEP_BUTTON);\n}\n\nstatic void __init acpi_get_spcr_uart_addr(void)\n{\n	acpi_status status;\n	struct acpi_table_spcr *spcr_ptr;\n\n	status = acpi_get_table(ACPI_SIG_SPCR, 0,\n				(struct acpi_table_header **)&spcr_ptr);\n	if (ACPI_FAILURE(status)) {\n		pr_warn(\"STAO table present, but SPCR is missing\\n\");\n		return;\n	}\n\n	spcr_uart_addr = spcr_ptr->serial_port.address;\n	acpi_put_table((struct acpi_table_header *)spcr_ptr);\n}\n\nstatic bool acpi_scan_initialized;\n\nvoid __init acpi_scan_init(void)\n{\n	acpi_status status;\n	struct acpi_table_stao *stao_ptr;\n\n	acpi_pci_root_init();\n	acpi_pci_link_init();\n	acpi_processor_init();\n	acpi_platform_init();\n	acpi_lpss_init();\n	acpi_apd_init();\n	acpi_cmos_rtc_init();\n	acpi_container_init();\n	acpi_memory_hotplug_init();\n	acpi_watchdog_init();\n	acpi_pnp_init();\n	acpi_power_resources_init();\n	acpi_init_lpit();\n\n	acpi_scan_add_handler(&generic_device_handler);\n\n	/*\n	 * If there is STAO table, check whether it needs to ignore the UART\n	 * device in SPCR table.\n	 */\n	status = acpi_get_table(ACPI_SIG_STAO, 0,\n				(struct acpi_table_header **)&stao_ptr);\n	if (ACPI_SUCCESS(status)) {\n		if (stao_ptr->header.length > sizeof(struct acpi_table_stao))\n			pr_info(\"STAO Name List not yet supported.\\n\");\n\n		if (stao_ptr->ignore_uart)\n			acpi_get_spcr_uart_addr();\n\n		acpi_put_table((struct acpi_table_header *)stao_ptr);\n	}\n\n	acpi_gpe_apply_masked_gpes();\n	acpi_update_all_gpes();\n\n	/*\n	 * Although we call __add_memory() that is documented to require the\n	 * device_hotplug_lock, it is not necessary here because this is an\n	 * early code when userspace or any other code path cannot trigger\n	 * hotplug/hotunplug operations.\n	 */\n	mutex_lock(&acpi_scan_lock);\n	/*\n	 * Enumerate devices in the ACPI namespace.\n	 */\n	if (acpi_bus_scan(ACPI_ROOT_OBJECT))\n		goto unlock;\n\n	acpi_root = acpi_fetch_acpi_dev(ACPI_ROOT_OBJECT);\n	if (!acpi_root)\n		goto unlock;\n\n	/* Fixed feature devices do not exist on HW-reduced platform */\n	if (!acpi_gbl_reduced_hardware)\n		acpi_bus_scan_fixed();\n\n	acpi_turn_off_unused_power_resources();\n\n	acpi_scan_initialized = true;\n\nunlock:\n	mutex_unlock(&acpi_scan_lock);\n}\n\nstatic struct acpi_probe_entry *ape;\nstatic int acpi_probe_count;\nstatic DEFINE_MUTEX(acpi_probe_mutex);\n\nstatic int __init acpi_match_madt(union acpi_subtable_headers *header,\n				  const unsigned long end)\n{\n	if (!ape->subtable_valid || ape->subtable_valid(&header->common, ape))\n		if (!ape->probe_subtbl(header, end))\n			acpi_probe_count++;\n\n	return 0;\n}\n\nvoid __weak arch_sort_irqchip_probe(struct acpi_probe_entry *ap_head, int nr) { }\n\nint __init __acpi_probe_device_table(struct acpi_probe_entry *ap_head, int nr)\n{\n	int count = 0;\n\n	if (acpi_disabled)\n		return 0;\n\n	mutex_lock(&acpi_probe_mutex);\n	arch_sort_irqchip_probe(ap_head, nr);\n	for (ape = ap_head; nr; ape++, nr--) {\n		if (ACPI_COMPARE_NAMESEG(ACPI_SIG_MADT, ape->id)) {\n			acpi_probe_count = 0;\n			acpi_table_parse_madt(ape->type, acpi_match_madt, 0);\n			count += acpi_probe_count;\n		} else {\n			int res;\n			res = acpi_table_parse(ape->id, ape->probe_table);\n			if (!res)\n				count++;\n		}\n	}\n	mutex_unlock(&acpi_probe_mutex);\n\n	return count;\n}\n\nstatic void acpi_table_events_fn(struct work_struct *work)\n{\n	acpi_scan_lock_acquire();\n	acpi_bus_scan(ACPI_ROOT_OBJECT);\n	acpi_scan_lock_release();\n\n	kfree(work);\n}\n\nvoid acpi_scan_table_notify(void)\n{\n	struct work_struct *work;\n\n	if (!acpi_scan_initialized)\n		return;\n\n	work = kmalloc_obj(*work);\n	if (!work)\n		return;\n\n	INIT_WORK(work, acpi_table_events_fn);\n	schedule_work(work);\n}\n\nint acpi_reconfig_notifier_register(struct notifier_block *nb)\n{\n	return blocking_notifier_chain_register(&acpi_reconfig_chain, nb);\n}\nEXPORT_SYMBOL(acpi_reconfig_notifier_register);\n\nint acpi_reconfig_notifier_unregister(struct notifier_block *nb)\n{\n	return blocking_notifier_chain_unregister(&acpi_reconfig_chain, nb);\n}\nEXPORT_SYMBOL(acpi_reconfig_notifier_unregister);\n";

